{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/app-main.json
    The main column of AppShell: the heading, the metric tiles, and the chart panel (beside the activity panel when `activity` is given).
    Props (p): id, title, metrics, chart, activity, cols, density. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_metrics = ($p['metrics'] ?? null)}
{var $v_chart = ($p['chart'] ?? null)}
{var $v_activity = ($p['activity'] ?? null)}
{var $v_cols = ($p['cols'] ?? '1-2')}
{var $v_density = ($p['density'] ?? 'default')}
{capture $c_8}
  {capture $c_1}
    {=og_text($v_title)}
  {/capture}
  {=og_include('compose/Title.latte', ['as' => 2, 'size' => '2xl', 'weight' => 'bold', 'attrs' => og_attrs(['id', og_tpl('{0}-title', [$v_id])]), 'children' => (string) $c_1])|noescape}
  {if og_t(og_gt(og_len($v_metrics), 0))}
    {capture $c_3}
      {foreach og_l($v_metrics) as $v_m}
        {capture $c_2}
          {=og_include('blocks/stat-tile.latte', ['p' => ['label' => og_get($v_m, ['label']), 'value' => og_get($v_m, ['value']), 'icon' => og_get($v_m, ['icon']), 'hint' => og_get($v_m, ['hint'])]])|noescape}
        {/capture}
        {=og_include('compose/Box.latte', ['attrs' => og_attrs(['data-testid', 'item']), 'children' => (string) $c_2])|noescape}
      {/foreach}
    {/capture}
    {=og_include('compose/Grid.latte', ['cols' => og_s($v_cols), 'class' => 'gap-4', 'attrs' => og_attrs(['data-testid', 'items']), 'children' => (string) $c_3])|noescape}
  {/if}
  {if og_t($v_activity)}
    {capture $c_6}
      {if og_t(og_gt(og_len(og_get($v_chart, ['series'])), 0))}
        {capture $c_4}
          {=og_include('blocks/bar-chart.latte', ['p' => ['bars' => og_get($v_chart, ['series']), 'label' => og_get($v_chart, ['summary']), 'height' => 144]])|noescape}
        {/capture}
        {=og_include('blocks/panel.latte', ['p' => ['title' => og_get($v_chart, ['title']), 'description' => og_get($v_chart, ['text']), 'id' => og_tpl('{0}-chart', [$v_id]), 'className' => og_cnv(['h-full'])], 'children' => og_markup($c_4)])|noescape}
      {/if}
      {if og_t(og_gt(og_len(og_get($v_activity, ['events'])), 0))}
        {capture $c_5}
          {=og_include('blocks/timeline.latte', ['p' => ['items' => og_get($v_activity, ['events'])]])|noescape}
        {/capture}
        {=og_include('blocks/panel.latte', ['p' => ['title' => og_get($v_activity, ['title']), 'description' => og_get($v_activity, ['text']), 'id' => og_tpl('{0}-feed', [$v_id]), 'className' => og_cnv(['h-full'])], 'children' => og_markup($c_5)])|noescape}
      {/if}
    {/capture}
    {=og_include('compose/Grid.latte', ['cols' => '1-2', 'class' => 'items-stretch gap-4', 'children' => (string) $c_6])|noescape}
  {elseif og_t(og_gt(og_len(og_get($v_chart, ['series'])), 0))}
    {capture $c_7}
      {=og_include('blocks/bar-chart.latte', ['p' => ['bars' => og_get($v_chart, ['series']), 'label' => og_get($v_chart, ['summary']), 'height' => 144]])|noescape}
    {/capture}
    {=og_include('blocks/panel.latte', ['p' => ['title' => og_get($v_chart, ['title']), 'description' => og_get($v_chart, ['text']), 'id' => og_tpl('{0}-chart', [$v_id]), 'className' => og_cnv(['h-full'])], 'children' => og_markup($c_7)])|noescape}
  {/if}
{/capture}
{=og_include('compose/Stack.latte', ['gap' => og_s((og_t(og_eq($v_density, 'compact')) ? '4' : '6')), 'align' => 'stretch', 'class' => 'min-w-0', 'attrs' => og_attrs(['data-testid', 'app-main']), 'children' => (string) $c_8])|noescape}
